const HomologacaoPage: React.FC<{ currentUser: User; userPermissions: string[]; hasGlobalView?: boolean }> = ({ currentUser, userPermissions, hasGlobalView }) => {
    const [entries, setEntries] = useState<HomologacaoEntry[]>([]);
    const [checkins, setCheckins] = useState<ChecklistEntry[]>([]);
    const [systemUsers, setSystemUsers] = useState<User[]>([]);
    const [homologationUsers, setHomologationUsers] = useState<User[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const [activeMainTab, setActiveMainTab] = useState<'pendentes' | 'concluidas'>('pendentes');

    const [isModalOpen, setModalOpen] = useState(false);
    const [editingEntryId, setEditingEntryId] = useState<string | null>(null);
    const [isViewCheckinModalOpen, setViewCheckinModalOpen] = useState(false);
    const [isConfirmFinalizeModalOpen, setIsConfirmFinalizeModalOpen] = useState(false);
    const [entryToFinalize, setEntryToFinalize] = useState<HomologacaoEntry | null>(null);
    const [activeCheckinStep, setActiveCheckinStep] = useState(1);
    const [selectedCheckin, setSelectedCheckin] = useState<ChecklistEntry | null>(null);
    const [hdPhoto, setHdPhoto] = useState<string | null>(null);

    const [isSuccessModalOpen, setSuccessModalOpen] = useState(false);
    const [modalMessage, setModalMessage] = useState('');

    const [form, setForm] = useState<Partial<HomologacaoEntry>>({
        checkinId: '',
        clientName: '',
        responsible_user_id: '',
        status: 'Em Análise',
        files: {
            procuracao: [],
            contaEnergia: [],
            documentoFoto: []
        }
    });

    const handleSuccessModalClose = () => {
        setSuccessModalOpen(false);
    };

    const isMasterAdmin = useMemo(() => String(currentUser.profileId) === ADMIN_PROFILE_ID, [currentUser]);

    const loadData = async () => {
        setIsLoading(true);
        try {
            const [homoData, checkinData, userData, profileData] = await Promise.all([
                dataService.getAll<HomologacaoEntry>('homologacao_entries', currentUser.id, isMasterAdmin),
                dataService.getAll<ChecklistEntry>('checklist_checkin', undefined, true), 
                dataService.getAll<User>('system_users', undefined, true),
                dataService.getAll<UserProfile>('system_profiles', undefined, true)
            ]) as [HomologacaoEntry[], ChecklistEntry[], User[], UserProfile[]];

            setEntries(homoData.sort((a, b) => b.date.localeCompare(a.date)));
            setCheckins(checkinData);
            setSystemUsers(userData);

            const homologationProfiles = profileData.filter(p => 
                p.name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").includes('homologacao')
            ).map(p => p.id);

            const hUsers = userData.filter(u => homologationProfiles.includes(u.profileId));
            setHomologationUsers(hUsers);

        } catch (e) {
            console.error("Erro ao carregar homologações:", e);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        loadData();
    }, [currentUser.id, isMasterAdmin]);

    const filteredEntries = useMemo(() => {
        return entries.filter(e => {
            const matchesSearch = e.clientName.toLowerCase().includes(searchTerm.toLowerCase());
            const isCompleted = e.status === 'Aprovada';
            const matchesTab = activeMainTab === 'concluidas' ? isCompleted : !isCompleted;
            const isResponsible = e.responsible_user_id === currentUser.id;
            const canSee = isMasterAdmin || isResponsible;
            return matchesSearch && matchesTab && canSee;
        });
    }, [entries, searchTerm, activeMainTab, isMasterAdmin, currentUser.id]);

    const handleEditEntry = (entry: HomologacaoEntry) => {
        setEditingEntryId(entry.id);
        setForm({
            checkinId: entry.checkinId,
            clientName: entry.clientName,
            responsible_user_id: entry.responsible_user_id,
            status: entry.status,
            files: {
                procuracao: entry.files?.procuracao || [],
                contaEnergia: entry.files?.contaEnergia || [],
                documentoFoto: entry.files?.documentoFoto || []
            },
            observations: entry.observations
        });
        setModalOpen(true);
    };

    const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>, field: keyof HomologacaoEntry['files']) => {
        const files = e.target.files;
        if (!files || files.length === 0) return;

        Array.from(files).forEach(file => {
            const reader = new FileReader();
            reader.onload = (event) => {
                if (typeof event.target?.result === 'string') {
                    const attachment: ExpenseAttachment = {
                        name: file.name,
                        data: event.target.result
                    };
                    setForm(prev => ({
                        ...prev,
                        files: {
                            ...(prev.files || {}),
                            [field]: [...(prev.files?.[field] || []), attachment]
                        }
                    }));
                }
            };
            reader.readAsDataURL(file);
        });
        e.target.value = '';
    };

    const handleRemoveFile = (field: keyof HomologacaoEntry['files'], index: number) => {
        setForm(prev => {
            const currentFiles = [...(prev.files?.[field] || [])];
            currentFiles.splice(index, 1);
            return {
                ...prev,
                files: {
                    ...(prev.files || {}),
                    [field]: currentFiles
                }
            };
        });
    };

    const handleSelectCheckin = (checkinId: string) => {
        const checkin = checkins.find(c => String(c.id) === String(checkinId));
        if (checkin) {
            setForm(prev => ({
                ...prev,
                checkinId: String(checkin.id),
                clientName: checkin.project 
            }));
        } else {
            setForm(prev => ({ ...prev, checkinId: '', clientName: '' }));
        }
    };

    const handleSave = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!form.checkinId || !form.clientName || !form.responsible_user_id) {
            alert("Por favor, preencha todos os campos obrigatórios.");
            return;
        }

        setIsSaving(true);
        try {
            const entry: HomologacaoEntry = {
                id: editingEntryId || `homo-${Date.now()}`,
                owner_id: editingEntryId ? entries.find(e => e.id === editingEntryId)?.owner_id || currentUser.id : currentUser.id,
                responsible_user_id: form.responsible_user_id,
                checkinId: form.checkinId!,
                clientName: form.clientName!,
                date: editingEntryId ? entries.find(e => e.id === editingEntryId)?.date || new Date().toISOString() : new Date().toISOString(),
                status: (form.status as any) || 'Em Análise',
                files: form.files as any,
                observations: form.observations
            };

            await dataService.save('homologacao_entries', entry);
            setModalOpen(false);
            setEditingEntryId(null);
            setForm({ checkinId: '', clientName: '', responsible_user_id: '', status: 'Em Análise', files: { procuracao: [], contaEnergia: [], documentoFoto: [] } });
            setModalMessage(editingEntryId ? "Homologação atualizada!" : "Homologação registrada!");
            setSuccessModalOpen(true);
            await loadData();
        } catch (e) {
            alert("Erro ao salvar.");
        } finally {
            setIsSaving(false);
        }
    };

    const handleConfirmFinalize = async () => {
        if (!entryToFinalize) return;
        setIsSaving(true);
        try {
            await dataService.save('homologacao_entries', { ...entryToFinalize, status: 'Aprovada' });
            setModalMessage("Processo concluído com sucesso!");
            setSuccessModalOpen(true);
            await loadData();
            setIsConfirmFinalizeModalOpen(false);
            setEntryToFinalize(null);
        } catch (e) {
            alert("Erro ao atualizar status.");
        } finally {
            setIsSaving(false);
        }
    };

    const handleDelete = async (id: string) => {
        if (!confirm("Deseja realmente excluir este registro?")) return;
        try {
            await dataService.delete('homologacao_entries', id);
            await loadData();
        } catch (e) {
            alert("Erro ao excluir.");
        }
    };

    const handleViewCheckin = (checkinId: string) => {
        const checkin = checkins.find(c => String(c.id) === String(checkinId));
        if (checkin) {
            setSelectedCheckin(checkin);
            setActiveCheckinStep(1);
            setViewCheckinModalOpen(true);
        } else {
            alert("Dados técnicos do check-in não encontrados ou indisponíveis.");
        }
    };

    const getFileBlob = (file: ExpenseAttachment): Blob => {
        const parts = file.data.split(';base64,');
        const contentType = parts[0].split(':')[1];
        const raw = window.atob(parts[1]);
        const uInt8Array = new Uint8Array(raw.length);
        for (let i = 0; i < raw.length; ++i) { uInt8Array[i] = raw.charCodeAt(i); }
        return new Blob([uInt8Array], { type: contentType });
    };

    const handleViewFile = (file: ExpenseAttachment) => {
        const isPdf = file.name.toLowerCase().endsWith('.pdf') || file.data.startsWith('data:application/pdf');
        if (isPdf) {
            const blob: Blob = getFileBlob(file);
            const url = URL.createObjectURL(blob);
            window.open(url, '_blank');
        } else {
            setHdPhoto(file.data);
        }
    };

    const handleDownload = (file: ExpenseAttachment) => {
        const blob: Blob = getFileBlob(file);
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = file.name;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    };

    const renderFilePreview = (label: string, files: ExpenseAttachment[] = [], field: keyof HomologacaoEntry['files']) => {
        return (
            <div className="bg-gray-50 dark:bg-gray-900/50 p-3 rounded-2xl border border-gray-100 dark:border-gray-700 flex flex-col gap-2">
                <FormLabel>{label}</FormLabel>

                <div className="space-y-2">
                    {files.map((file, idx) => {
                        const isPdf = file.name.toLowerCase().endsWith('.pdf') || file.data.startsWith('data:application/pdf');
                        return (
                            <div key={idx} className="flex items-center justify-between gap-3 bg-white dark:bg-gray-800 p-2 rounded-xl border border-indigo-100 dark:border-indigo-900 shadow-sm group animate-fade-in">
                                <div className="flex items-center gap-2 overflow-hidden">
                                    {isPdf ? (
                                        <DocumentReportIcon className="w-4 h-4 text-red-500 shrink-0" />
                                    ) : (
                                        <div className="w-6 h-6 rounded overflow-hidden shrink-0 border border-gray-100">
                                            <img src={file.data} className="w-full h-full object-cover" alt="" />
                                        </div>
                                    )}
                                    <span className="text-[9px] font-bold text-gray-700 dark:text-gray-200 truncate">{file.name}</span>
                                </div>
                                <div className="flex gap-1 shrink-0">
                                    <button type="button" onClick={() => handleViewFile(file)} className="p-1 bg-indigo-50 text-indigo-600 rounded-lg hover:bg-indigo-100 transition-all"><EyeIcon className="w-3 h-3" /></button>
                                    <button type="button" onClick={() => handleDownload(file)} className="p-1 bg-green-50 text-green-600 rounded-lg hover:bg-green-100 transition-all"><ArrowDownIcon className="w-3 h-3" /></button>
                                    {!isSaving && (
                                        <button type="button" onClick={() => handleRemoveFile(field, idx)} className="p-1 bg-red-50 text-red-500 rounded-lg hover:bg-red-100 transition-all"><TrashIcon className="w-3 h-3" /></button>
                                    )}
                                </div>
                            </div>
                        );
                    })}
                </div>

                <label className="flex flex-col items-center justify-center py-4 px-4 bg-white dark:bg-gray-800 border-2 border-dashed border-indigo-100 dark:border-indigo-900 rounded-2xl cursor-pointer hover:border-indigo-300 hover:bg-indigo-50/20 transition-all group">
                    <UploadIcon className="w-5 h-5 text-indigo-400 group-hover:scale-110 transition-transform" />
                    <span className="text-[9px] font-black text-indigo-600 mt-1.5">Anexar arquivos</span>
                    <input type="file" multiple className="hidden" accept="image/*,application/pdf" onChange={(e) => handleFileUpload(e, field)} />
                </label>
            </div>
        );
    };

    const renderCheckinGalleryItem = (label: string, photos: string[] = []) => {
        if (!photos || photos.length === 0) return null;
        return (
            <div className="p-4 bg-white dark:bg-gray-800 rounded-2xl border border-gray-100 dark:border-gray-700 space-y-3">
                <label className="text-[10px] font-black text-gray-400 block tracking-tight">{label}</label>
                <div className="grid grid-cols-4 gap-2">
                    {photos.map((url, idx) => (
                        <div key={idx} className="relative aspect-square rounded-xl overflow-hidden shadow-sm group border border-gray-50 dark:border-gray-700 bg-gray-50">
                            <img src={url} className="w-full h-full object-cover" alt="" />
                            <div className="absolute inset-0 bg-black/50 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-1.5">
                                <button onClick={() => setHdPhoto(url)} className="p-1.5 bg-white text-gray-900 rounded-lg shadow-lg hover:bg-indigo-50"><EyeIcon className="w-4 h-4" /></button>
                                <button onClick={() => {
                                    const a = document.createElement('a');
                                    a.href = url;
                                    a.download = `foto-${label.toLowerCase().replace(/\s/g, '-')}-${idx}.jpg`;
                                    a.click();
                                }} className="p-1.5 bg-green-600 text-white rounded-lg shadow-lg hover:bg-green-700"><ArrowDownIcon className="w-4 h-4" /></button>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        );
    };

    return (
        <div className="space-y-6 animate-fade-in pb-20">
            <header className="flex flex-col sm:flex-row justify-between items-start sm:items-center bg-white dark:bg-gray-800 p-6 rounded-3xl shadow-xl border border-gray-100 dark:border-gray-700 gap-4">
                <div className="flex items-center gap-4">
                    <div className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg shadow-indigo-600/20">
                        <DocumentReportIcon className="w-8 h-8" />
                    </div>
                    <div>
                        <h2 className="text-2xl font-black text-gray-800 dark:text-white tracking-tight leading-none">Homologação</h2>
                        <p className="text-[11px] text-gray-400 font-bold mt-2 tracking-tight">Processos de concessionária</p>
                    </div>
                </div>
                <button 
                    onClick={() => { setEditingEntryId(null); setForm({ checkinId: '', clientName: '', responsible_user_id: '', status: 'Em Análise', files: { procuracao: [], contaEnergia: [], documentoFoto: [] } }); setModalOpen(true); }} 
                    className="px-6 py-3 bg-indigo-600 text-white rounded-2xl font-black text-xs shadow-xl hover:bg-indigo-700 transition-all active:scale-95 flex items-center gap-2"
                >
                    <PlusIcon className="w-5 h-5" /> Nova homologação
                </button>
            </header>

            <div className="flex flex-col md:flex-row items-center justify-between gap-4">
                <div className="flex bg-white dark:bg-gray-800 p-1.5 rounded-2xl shadow-sm border border-gray-100 dark:border-gray-700 w-fit">
                    <button onClick={() => setActiveMainTab('pendentes')} className={`px-6 py-2 rounded-xl font-black text-xs transition-all ${activeMainTab === 'pendentes' ? 'bg-indigo-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}>Pendentes</button>
                    <button onClick={() => setActiveMainTab('concluidas')} className={`px-6 py-2 rounded-xl font-black text-xs transition-all ${activeMainTab === 'concluidas' ? 'bg-green-600 text-white shadow-lg' : 'text-gray-400 hover:text-gray-600'}`}>Concluídas</button>
